<?php
// Local visual review only. Never execute application PHP or accept writes.
if (!in_array($_SERVER['REMOTE_ADDR'] ?? '', ['127.0.0.1', '::1'], true)) {
    http_response_code(403); exit;
}
if (!in_array($_SERVER['REQUEST_METHOD'], ['GET', 'HEAD'], true)) {
    http_response_code(405); header('Allow: GET, HEAD'); exit('Local preview: writes disabled.');
}
$path = rawurldecode(parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH) ?? '');
if ($path === '/') $path = '/.local/ui-review.html';
$root = realpath(dirname(__DIR__));
// Read-only polling snapshots generated by the no-DB smoke tests.
if ($path === '/pm_ajax.php') {
    parse_str($_SERVER['QUERY_STRING'] ?? '', $query);
    $snapshots = ['pmcosts'=>'phase6-preview.json', 'pmallocations'=>'phase7-preview.json'];
    $op = $query['op'] ?? '';
    if (!is_string($op) || !isset($snapshots[$op]) || !is_file($root.'/.local/'.$snapshots[$op])) {
        http_response_code(404); exit('Preview snapshot unavailable.');
    }
    header('Content-Type: application/json; charset=UTF-8');
    header('Cache-Control: no-store');
    if ($_SERVER['REQUEST_METHOD'] !== 'HEAD') readfile($root.'/.local/'.$snapshots[$op]);
    exit;
}
$file = realpath($root.$path);
$allowed = preg_match('~^/\.local/(ui-review|review-[a-z0-9-]+)\.html$~D', $path)
    || preg_match('~^/(css|js|assets)/[a-zA-Z0-9_./-]+\.(css|js|woff2|png|svg|ico)$~D', $path);
if (!$allowed || str_contains($path, '..') || !$file || !str_starts_with($file, $root.DIRECTORY_SEPARATOR) || !is_file($file)) {
    http_response_code(404); exit('Local preview: route unavailable.');
}
$types = ['html'=>'text/html; charset=UTF-8','css'=>'text/css; charset=UTF-8','js'=>'text/javascript; charset=UTF-8','woff2'=>'font/woff2','png'=>'image/png','svg'=>'image/svg+xml','ico'=>'image/x-icon'];
header('Content-Type: '.$types[pathinfo($file, PATHINFO_EXTENSION)]);
header('Cache-Control: no-store');
header('X-Content-Type-Options: nosniff');
if ($_SERVER['REQUEST_METHOD'] !== 'HEAD') readfile($file);
